func NewTriImpl() Trie {
	return Trie{
		words: make(map[string]bool, 0),
		index: make(map[string]bool, 0),
	}
}

func (t *Trie) Insert(word string) {
	t.words[word] = true
	prefix := ""
	for _, c := range word {
		prefix += string(c)
		t.index[prefix] = true
	}
}

func (t *Trie) Search(word string) bool {
	_, isExist := t.words[word]
	if isExist {
		return true
	}
	return false
}

func (t *Trie) StartsWith(prefix string) bool {
	_, isExist := t.index[prefix]
	if isExist {
		return true
	}
	return false
}

var trie Trie
var boardArr [][]byte
var result []string
var isAdded map[string]bool

func findWords(board [][]byte, words []string) []string {
	boardArr = board
	isAdded = make(map[string]bool, 0)
	trie = NewTriImpl()
	for _, word := range words {
		trie.Insert(word)
	}
	result = make([]string, 0)
	for j := 0; j < len(board); j++ {
		for k := 0; k < len(board[0]); k++ {
			isVisited := make([][]bool, len(board))
			for j := 0; j < len(board); j++ {
				isVisited[j] = make([]bool, len(board[0]))
			}
			searchWord(j, k, "", isVisited)
		}
	}
	return result
}

func searchWord(row, col int, prefix string, isVisited [][]bool) {
	if row < 0 || row >= len(boardArr) || col < 0 || col >= len(boardArr[0]) {
		return
	}
	if isVisited[row][col] {
		return
	}
	prefix += string(boardArr[row][col])
	if !trie.StartsWith(prefix) {
		return
	}
	if trie.Search(prefix) && !isAdded[prefix] {
		result = append(result, prefix)
		isAdded[prefix] = true
	}
	isVisited[row][col] = true
	searchWord(row+1, col, prefix, isVisited)
	searchWord(row-1, col, prefix, isVisited)
	searchWord(row, col+1, prefix, isVisited)
	searchWord(row, col-1, prefix, isVisited)
	isVisited[row][col] = false
}

class Solution(object):
    def findWords(self, board, words):
        """
        :type board: List[List[str]]
        :type words: List[str]
        :rtype: List[str]
        """
        # build trie
        self.trie = {}
        for word in words:
            node = self.trie
            for c in word:
                if c not in node:
                    node[c] = {}
                node = node[c]
            node["$"]=word

        # DFS from each cell in board
        self.board = board
        self.result = set()
        self.visited = []
        self.reset_visited()

        for i in range(len(board)):
            for j in range(len(board[0])):
                self.dfs(i, j, self.trie)

        return list(self.result)

    def reset_visited(self):
        self.visited = []
        for i in range(len(self.board)):
            row = []
            for j in range(len(self.board[0])):
                row.append(False)
            self.visited.append(row)

    def dfs(self, x, y, node):
        c = self.board[x][y]
        if c not in node:
            return

        node = node[c]
        if "$" in node:
            self.result.add(node['$'])

        self.visited[x][y] = True
        for dx, dy in [(0,1),(1,0), (-1,0), (0,-1)]:
            if 0<=x+dx<len(self.board) and 0<=y+dy<len(self.board[0]) and not self.visited[x+dx][y+dy]:
                self.dfs(x+dx, y+dy, node)
        self.visited[x][y]=False

class Solution(object):
    def findWords(self, board, words):
        """
        :type board: List[List[str]]
        :type words: List[str]
        :rtype: List[str]
        """
        m, n = len(board), len(board[0])

        root = {}
        for word in words:
            p = root
            for c in word:
                if c not in p:
                    p[c] = {}
                p = p[c]
            p["finish"] = word

        def dfs(i, j, p):
            c = board[i][j]
            if "finish" in p[c]:
                ans.append(p[c]["finish"])
                del p[c]["finish"]
            board[i][j] = "#"
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                ni, nj = i + dx, j + dy
                if 0 <= ni < m and 0 <= nj < n and board[ni][nj] in p[c]:
                    dfs(ni, nj, p[c])
            board[i][j] = c
            if not p[c]:
                del p[c]

        ans = []
        for i in range(m):
            for j in range(n):
                if board[i][j] in root:
                    dfs(i, j, root)
        return ans

